 "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#86efac\">¿Es verdad?</b><br><span style=\"font-size:22px;color:#d6d3ee\">Contrastar con fuentes</span></div>": "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#86efac\">Stimmt es?</b><br><span style=\"font-size:22px;color:#d6d3ee\">Mit Quellen gegenprüfen</span></div>",
 "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">¿Es justo?</b><br><span style=\"font-size:22px;color:#d6d3ee\">Acceso igual para todos</span></div>": "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">Ist es gerecht?</b><br><span style=\"font-size:22px;color:#d6d3ee\">Gleicher Zugang für alle</span></div>",
